import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Probabilità statistica","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lced.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lced.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lced.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="probabilita-statistica" tabindex="-1">Probabilità statistica <a class="header-anchor" href="#probabilita-statistica" aria-label="Permalink to “Probabilità statistica”">​</a></h1><p>Il fatto che la frequenza, all&#39;aumentare del numero delle prove fatte, tenda al valore della probabilità classica ci fa pensare che in fenomeni in cui la probabilità classica non è applicabile sia possibile considerare la frequenza di eventi già accaduti e considerarla come probabilità di eventi futuri.</p><p>Cioè in eventi in cui non si può applicare la probabilità classica, ma si possano fare numerose prove possiamo considerare la frequenza degli eventi già accaduti come probabilità per gli eventi dello stesso tipo che potranno accadere. In tale caso parleremo di probabilità statistica.</p><blockquote><p><strong>Definizione:</strong> La probabilità statistica di un evento casuale (aleatorio) è un numero che esprime la frequenza relativa dell&#39;evento in un gran numero di prove precedenti tutte fatte nelle stesse condizioni.</p></blockquote><blockquote><p><strong>Esempio:</strong> Per costruire le tabelle di probabilità di vita e di morte che usano le assicurazioni sulla vita si calcolano le frequenze dei decessi relativamente alle varie fasce di età consultando gli archivi anagrafici comunali.</p></blockquote><p>Va da sé che per la probabilità statistica valgono tutte le proprietà e tutti i teoremi già visti per la probabilità classica.</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};